import{_ as r,o as e,c as o,ai as d}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"WMS 仓储管理系统","description":"","frontmatter":{},"headers":[],"relativePath":"instances/industrial/wms.md","filePath":"instances/industrial/wms.md"}'),c={name:"instances/industrial/wms.md"},a={viewBox:"0 0 880 180",width:"100%",style:{"max-width":"100%",height:"auto",display:"block"},xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"WMS 功能架构图"},s={viewBox:"0 0 880 292",width:"100%",style:{"max-width":"100%",height:"auto",display:"block"},xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"WMS 分层结构图"};function i(n,t,l,p,h,v){return e(),o("div",null,[t[2]||(t[2]=d('<h1 id="wms-仓储管理系统" tabindex="-1">WMS 仓储管理系统 <a class="header-anchor" href="#wms-仓储管理系统" aria-label="Permalink to “WMS 仓储管理系统”">​</a></h1><div class="sys-hero"><div class="sys-hero__eyebrow">02 工业数字化 · 优先级 3 / 3</div><div class="sys-hero__badges"><span class="sys-badge sys-badge--ok">✅ 已跑通（收货 → 上架 → 拣货 → 发货全链路）</span><span class="sys-badge">Java 21 · Spring Boot 3</span><span class="sys-badge">:18086 · openbiz_wms</span><span class="sys-badge">17 表 · 2 视图 · 2 触发器</span><span class="sys-badge">验收 297 项断言</span></div><p class="sys-hero__pitch">带批次与效期的工厂仓：货在哪、有多少、从哪来到哪去，账实对得上，先到期的先出，并发下单不超卖</p></div><blockquote><p>诚实边界：库存中心、入出库主链路、移库、盘点、退货、Excel / 打印、多租户、报表、PDA 扫码壳、操作日志页、CI/Docker、Swagger 都已实现（<code>docs/11</code> A/B/C 齐）。<strong>未做</strong>：上架策略与波次、库存冻结与手工调整、批次正反向追溯、与 MES/ERP 的 <code>/open/v1/**</code> 开放接口（设计有、代码未实装）、万级 SKU 吞吐。<code>PRODUCTION</code> / <code>PICKING</code> 目前是可存枚举，走同一主链路，无专属分支。中小自营仓日常作业大约覆盖 <strong>70%～80%</strong>；3PL / 立库 / 波次拣货不在范围。</p></blockquote><h2 id="业务场景" tabindex="-1">业务场景 <a class="header-anchor" href="#业务场景" aria-label="Permalink to “业务场景”">​</a></h2><p><strong>一家什么样的仓</strong>：原料仓 + 成品仓，物料带批次与效期（食品、化工、汽配、医药中间体这类行业最常见）。仓管用 Excel 记账，月底盘一次，盘完调平。</p><table tabindex="0"><thead><tr><th>角色</th><th>在系统里做什么</th><th>没有系统时的样子</th></tr></thead><tbody><tr><td>收货员</td><td>收货登记，货进待检位并锁定</td><td>手写收货单，先堆在待检区，账上没数</td></tr><tr><td>质检员</td><td>逐行判定 PASS / FAIL</td><td>结果回填不及时，货已经被上架了</td></tr><tr><td>上架工</td><td>按库位建议上架，落流水</td><td>哪有空位放哪，找货靠老员工记忆</td></tr><tr><td>拣货员</td><td>按 FEFO 分配结果拣货</td><td>凭手感拿，临期货压到过期才报废</td></tr><tr><td>复核员</td><td>复核发货，扣减库存并落流水</td><td>发多发少没人核，差异留到月底</td></tr><tr><td>仓管主管</td><td>看三态余额与对账差异</td><td>盘库靠点数，差异拍脑袋调平</td></tr></tbody></table><p><strong>这段业务真正难的地方是账实一致</strong>：库存从来不是一个数字，而是「在手 / 已占 / 锁定」三个数加一本只能追加的流水。少一个维度就会出现两种典型事故——把已分配未发货的货又卖一次（超卖），或者账面有货实物没有（盘亏说不清）。</p><p>三条落到业务上的硬约束：</p><ul><li><strong>预占不动流水，只转移分配权</strong>：<code>SUM(流水) = on_hand</code> 才成立，否则对账口径直接作废</li><li><strong>冲红也走 INSERT</strong>：任何时点的库存都能重放出来，不是靠「最后改了一次」</li><li><strong>扣减走 CAS 条件更新</strong>：100 并发打同一 SKU 也不会为负</li></ul><h2 id="功能架构" tabindex="-1">功能架构 <a class="header-anchor" href="#功能架构" aria-label="Permalink to “功能架构”">​</a></h2>',10)),(e(),o("svg",a,[...t[0]||(t[0]=[d('<rect x="0" y="0" width="880" height="180" rx="14" fill="var(--vp-c-bg-soft)"></rect><text x="124" y="40" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">终端层</text><rect x="140" y="16" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="256" y="40" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">Vue3 管理端</text><rect x="384" y="16" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="500" y="40" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">PDA 扫码端</text><rect x="628" y="16" width="232" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="744" y="40" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">标签 / 电子秤</text><text x="124" y="98" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">应用层</text><rect x="140" y="74" width="134" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="207" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">入库管理</text><rect x="286" y="74" width="134" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="353" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">出库管理</text><rect x="433" y="74" width="134" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="500" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">移库 / 盘点</text><rect x="579" y="74" width="134" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="646" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">库存中心</text><rect x="726" y="74" width="134" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="793" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">策略引擎</text><text x="124" y="156" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">领域层</text><rect x="140" y="132" width="171" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="226" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">库位 · 三级结构</text><rect x="323" y="132" width="171" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="408" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">批次 · 效期</text><rect x="506" y="132" width="171" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="591" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">单据状态机</text><rect x="689" y="132" width="171" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="774" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">扣减 · 预占</text>',28)])])),t[3]||(t[3]=d(`<p>实心高亮 = 已实现：<strong>入库 · 出库 · 移库 / 盘点 · 库存中心 · 扣减预占</strong>。空心为 P1 / P2：库内策略（上架策略、波次拣货，明确不做）、策略引擎、标签设备对接。</p><h2 id="核心亮点" tabindex="-1">核心亮点 <a class="header-anchor" href="#核心亮点" aria-label="Permalink to “核心亮点”">​</a></h2><div class="sys-grid"><div class="sys-card"><div class="sys-card__icon">📦</div><div class="sys-card__title">三态库存</div><div class="sys-card__desc">available / reserved / locked，单字段 qty 撑不住「已分配未发货」</div></div><div class="sys-card"><div class="sys-card__icon">🧾</div><div class="sys-card__title">不可篡改流水</div><div class="sys-card__desc">append-only 台账，冲红也走 INSERT，对账可复现任意时点</div></div><div class="sys-card"><div class="sys-card__icon">🔀</div><div class="sys-card__title">单据状态机</div><div class="sys-card__desc">入库 / 出库各有流转约束，非法跳转统一 409 拦截</div></div><div class="sys-card"><div class="sys-card__icon">🗺</div><div class="sys-card__title">三级库位</div><div class="sys-card__desc">仓 → 区 → 位，库存落到格，拣货才不用满仓找</div></div><div class="sys-card"><div class="sys-card__icon">⏳</div><div class="sys-card__title">批次 FEFO</div><div class="sys-card__desc">先到期先出，正反向追溯全靠流水串起来</div></div><div class="sys-card"><div class="sys-card__icon">🔒</div><div class="sys-card__title">并发不超卖</div><div class="sys-card__desc">CAS 条件更新 + 同事务落账，100 并发打同一 SKU 也不为负</div></div></div><h2 id="功能清单" tabindex="-1">功能清单 <a class="header-anchor" href="#功能清单" aria-label="Permalink to “功能清单”">​</a></h2><blockquote><p>状态图例：✅ 已实现并有验收断言 · 🔧 部分实现（字段/类型就位，专属业务分支未做） · 📋 待做</p></blockquote><h3 id="p0-·-最小闭环" tabindex="-1">P0 · 最小闭环 <a class="header-anchor" href="#p0-·-最小闭环" aria-label="Permalink to “P0 · 最小闭环”">​</a></h3><table tabindex="0"><thead><tr><th>功能域</th><th>功能</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>基础档案</td><td>仓库 / 库区 / 库位</td><td>✅</td><td>三级库位，树形维护 + 引用守卫</td></tr><tr><td>基础档案</td><td>SKU 物料主数据</td><td>✅</td><td>规格、单位、批次/效期开关</td></tr><tr><td>基础档案</td><td>批次 / 效期</td><td>✅</td><td>临期 30 天预警、过期拦截分配</td></tr><tr><td>入库</td><td>采购入库 <code>PURCHASE</code>（收货 → 上架）</td><td>✅</td><td>主路径，5 步状态机，类型缺省值</td></tr><tr><td>入库</td><td>退货入库 <code>RETURN</code></td><td>✅</td><td>必填 <code>ref_doc_no</code> 关联原出库单，按行校验可退量，累计不超原发；<code>verify_return.py</code> 17 项</td></tr><tr><td>入库</td><td>生产入库 <code>PRODUCTION</code></td><td>🔧</td><td>类型值可存、走同一主链路；MES 完工推送 <code>POST /open/v1/production-inbound</code> 仅有设计稿</td></tr><tr><td>库存</td><td>实时库存（三态余额）</td><td>✅</td><td>available / reserved / locked</td></tr><tr><td>库存</td><td>正确性扣减</td><td>✅</td><td>CAS 条件更新 + 同事务落账</td></tr><tr><td>库存</td><td>库存流水（append-only）</td><td>✅</td><td>不可篡改台账，触发器兜底</td></tr><tr><td>出库</td><td>销售出库 <code>SALES</code>（拣货 → 发货）</td><td>✅</td><td>主路径，6 步状态机，类型缺省值</td></tr><tr><td>出库</td><td>FEFO 分配</td><td>✅</td><td><code>expiry_date ASC</code>，过期批次不分配</td></tr><tr><td>出库</td><td>领料出库 <code>PICKING</code></td><td>🔧</td><td>类型值可存、走同一主链路；MES 领料 <code>POST /open/v1/picking-request</code> 仅有设计稿</td></tr><tr><td>出库</td><td>取消出库（释放预占）</td><td>✅</td><td>按 <code>wms_alloc</code> 行精确释放</td></tr><tr><td>库内作业</td><td>移库 / 调拨（建单 → 确认 → 作废）</td><td>✅</td><td><code>TF</code> 单号；确认时 CAS 扣源库位、加目标库位，落 <code>TRANSFER</code> 流水，<strong>净变动按库位对冲，不进收发存的出库口径</strong></td></tr><tr><td>库内作业</td><td>移库校验</td><td>✅</td><td>同库位 / <code>qty ≤ 0</code> / 库位或 SKU 不存在 → 400；重复确认由 <code>markDone</code> 影响 0 行兜住</td></tr><tr><td>库内作业</td><td>移库的自动化验收</td><td>✅</td><td><code>verify_transfer.py</code> · 作废 / 确认扣增 / TRANSFER 流水 / 同库位与超量拒绝 / 对账</td></tr></tbody></table><h3 id="交付补齐-工程-a-档" tabindex="-1">交付补齐（工程 A 档） <a class="header-anchor" href="#交付补齐-工程-a-档" aria-label="Permalink to “交付补齐（工程 A 档）”">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>Excel 导入导出（SKU / 库位 / 期初 / 单据）</td><td>✅</td><td><code>docs/12-sprint1-excel.md</code> · <code>verify_excel.py</code> 18 项</td></tr><tr><td>打印 / 条码模板</td><td>✅</td><td><code>docs/13-sprint1-print.md</code> · <code>verify_print.py</code> 16 项</td></tr><tr><td>退货入库 <code>RETURN</code></td><td>✅</td><td><code>ref_doc_no</code> 关联原出库；可退量累计 · <code>verify_return.py</code> 17 项</td></tr><tr><td>多租户对照验收</td><td>✅</td><td><code>admin2</code>@租户2 · <code>verify_tenant_isolation.py</code> 18 项</td></tr><tr><td>收发存 / 库龄 / 呆滞报表</td><td>✅</td><td><code>docs/16-sprint2-report.md</code> · <code>verify_report.py</code> 22 项，库龄四档 0-30 / 31-60 / 61-90 / 90+</td></tr><tr><td>移库 / 调拨验收</td><td>✅</td><td><code>docs/17-sprint2-transfer.md</code> · <code>verify_transfer.py</code> 22 项（源减目标增 / TRANSFER 流水 / 同库位与超量拒绝 / 对账健康）</td></tr><tr><td>盘点调平</td><td>✅</td><td>账面快照 + 四条拒绝路径（未盘完 / 盘亏吃预占 / 超量 / 重复提交）· <code>verify_stocktake.py</code> 35 项</td></tr><tr><td>盘点按库区 / 品类生成</td><td>✅</td><td><code>docs/19-sprint2-stocktake-scope.md</code> · <code>verify_stocktake_scope.py</code> 14 项</td></tr><tr><td>操作日志查询页</td><td>✅</td><td><code>docs/20-c4-operlog.md</code> · <code>verify_operlog.py</code></td></tr><tr><td>Docker / GitHub Actions CI</td><td>✅</td><td><code>docs/21-c2-ci-docker.md</code> · <code>ci/m2-seed</code> 注入私有底座 · GHA 前端 typecheck/build + <code>mvn test</code> · <code>Dockerfile</code> / <code>docker-compose.yml</code></td></tr><tr><td>API 文档（Swagger / springdoc）</td><td>✅</td><td><code>docs/22-c3-swagger.md</code> · <code>/swagger-ui.html</code> · <code>/v3/api-docs</code> · <code>verify_swagger.py</code></td></tr><tr><td>PDA 扫码端</td><td>✅</td><td><code>docs/18-sprint2-pda.md</code> · <code>verify_pda.py</code> 11 项；8 个 PDA 页面 + 统一 <code>GET /pda/resolve</code> 扫码解析，收货 / 上架 / 拣货 / 盘点复用原接口</td></tr><tr><td>RBAC / 审计 / 备份</td><td>✅</td><td>5 角色 46 项 · 操作留痕 15 项 · 备份恢复 16 项</td></tr></tbody></table><h3 id="p1-p2-·-路线" tabindex="-1">P1 / P2 · 路线 <a class="header-anchor" href="#p1-p2-·-路线" aria-label="Permalink to “P1 / P2 · 路线”">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>P1</td><td>ASN 预收货、上架策略（波次拣货明确不做）</td><td>📋</td></tr><tr><td>P1</td><td>库存冻结与手工调整（移库 / 调拨已完成，见上）</td><td>📋</td></tr><tr><td>P1</td><td>批次正反向追溯（FIFO / FEFO 分配已入 P0）</td><td>📋</td></tr><tr><td>P1</td><td>预警（上下限 / 效期）</td><td>📋</td></tr><tr><td>P1</td><td>ERP 订单 / MES 领料 OpenAPI</td><td>📋</td></tr><tr><td>P2</td><td>万级 SKU 吞吐优化（分桶 / 缓存 / 批量落库 / 分库）</td><td>📋</td></tr><tr><td>P2</td><td>TMS 发运、IIoT AGV/立库、多货主计费、行业模板</td><td>📋</td></tr></tbody></table><h2 id="核心流程" tabindex="-1">核心流程 <a class="header-anchor" href="#核心流程" aria-label="Permalink to “核心流程”">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>收货 ─▶ 质检 ─▶ 上架 ─▶ (流水 IN +N) ─▶ 拣货 ─▶ 复核 ─▶ 发货 ─▶ (流水 OUT -N)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>每一步对库存的副作用 —— 这是 WMS 唯一真正难的地方。注意 <code>available</code> 是生成列（<code>on_hand - reserved - locked</code>），没人直接写它，只改三态：</p><table tabindex="0"><thead><tr><th>环节</th><th><code>on_hand</code></th><th><code>reserved</code></th><th><code>locked</code></th><th>流水事件</th></tr></thead><tbody><tr><td>收货（入待检位）</td><td><code>+N</code></td><td>—</td><td><code>+N</code></td><td><code>INBOUND_RECEIVE</code></td></tr><tr><td>质检 PASS</td><td>—</td><td>—</td><td>—</td><td>无</td></tr><tr><td>质检 FAIL</td><td>—</td><td>—</td><td>—</td><td>无（货留在待检位，单据转 <code>QC_FAIL</code>）</td></tr><tr><td>上架（出待检位）</td><td><code>-N</code></td><td>—</td><td><code>-N</code></td><td><code>INBOUND_PUTAWAY</code></td></tr><tr><td>上架（入存储位）</td><td><code>+N</code></td><td>—</td><td>—</td><td><code>INBOUND_PUTAWAY</code></td></tr><tr><td>拣货分配</td><td>—</td><td><code>+N</code></td><td>—</td><td><strong>无</strong>（预占只转移分配权，不进流水）</td></tr><tr><td>复核</td><td>—</td><td>—</td><td>—</td><td>无（校验实物与单）</td></tr><tr><td>发货</td><td><code>-N</code></td><td><code>-N</code></td><td>—</td><td><code>OUTBOUND_SHIP</code></td></tr><tr><td>取消出库</td><td>—</td><td><code>-N</code></td><td>—</td><td><strong>无</strong>（按 <code>wms_alloc</code> 行释放）</td></tr><tr><td>移库确认</td><td>源 <code>-N</code> / 目标 <code>+N</code></td><td>—</td><td>—</td><td><code>TRANSFER</code> ×2（一出一入，合计净变动 0）</td></tr><tr><td>盘点调平</td><td><code>±diff</code></td><td>—</td><td>—</td><td><code>STOCKTAKE_ADJUST</code></td></tr></tbody></table><p>移库为什么单独用 <code>TRANSFER</code> 事件而不是「假出库 + 假入库」：一旦借用了出库口径，收发存报表会把内部搬货算成发货，月底对不上账。两条相反流水、同一 <code>doc_no</code>，净变动恒为 0，报表按事件类型就能把它们排除在外。</p><p>「预占不进流水」不是省事，是必须：<code>SUM(qty_change)</code> 必须等于 <code>on_hand</code>，否则对账口径直接作废。预占的正确性靠第二条独立校验 <code>v_wms_reserve_reconcile</code>（<code>reserved</code> = 未发货 alloc 合计）兜住。</p><h2 id="单据状态机" tabindex="-1">单据状态机 <a class="header-anchor" href="#单据状态机" aria-label="Permalink to “单据状态机”">​</a></h2><p><strong>入库单</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATED → RECEIVED → QC → PUTAWAY → DONE</span></span>
<span class="line"><span>              ↘ QC_FAIL（待检 / 退货分支）</span></span>
<span class="line"><span>任意未终态 → CANCELLED（已上架不可取消，只能冲红）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>出库单</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATED → ALLOCATED → PICKED → CHECKED → SHIPPED → DONE</span></span>
<span class="line"><span>             ↘ SHORT（缺货：回退 ALLOCATED 或部分发货）</span></span>
<span class="line"><span>任意未终态 → CANCELLED（SHIPPED 后不可取消）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>关键接口（前缀 <code>/api/wms</code>）：</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/inbound</code></td><td>建入库单</td></tr><tr><td>POST</td><td><code>/inbound/{id}/receive</code></td><td>收货登记（入待检位，<code>locked += n</code>）</td></tr><tr><td>POST</td><td><code>/inbound/{id}/qc</code></td><td>逐行质检 PASS / FAIL</td></tr><tr><td>POST</td><td><code>/inbound/{id}/putaway</code></td><td>上架（落流水）</td></tr><tr><td>POST</td><td><code>/outbound</code></td><td>建出库单</td></tr><tr><td>POST</td><td><code>/outbound/{id}/allocate</code></td><td>分配（FEFO 预占，返回 alloc 明细）</td></tr><tr><td>POST</td><td><code>/outbound/{id}/pick</code></td><td>拣货确认</td></tr><tr><td>POST</td><td><code>/outbound/{id}/ship</code></td><td>复核发货（扣减 + 流水）</td></tr><tr><td>POST</td><td><code>/outbound/{id}/cancel</code></td><td>取消（按 alloc 行释放）</td></tr><tr><td>GET</td><td><code>/stock</code> · <code>/stock/flow</code></td><td>三态余额 / 流水查询</td></tr><tr><td>GET</td><td><code>/stock/reconcile</code></td><td>两条对账校验，<code>diff &lt;&gt; 0</code> 即异常</td></tr><tr><td>POST</td><td><code>/transfer</code></td><td>建移库单（<code>fromLocationCode</code> / <code>toLocationCode</code> / <code>qty</code>）</td></tr><tr><td>POST</td><td><code>/transfer/{id}/confirm</code></td><td>执行移库：CAS 扣源库位、加目标库位，落 <code>TRANSFER</code> 流水</td></tr><tr><td>POST</td><td><code>/transfer/{id}/cancel</code></td><td>作废（仅 <code>CREATED</code>，与 MES 状态机同一套 409 约束）</td></tr><tr><td>POST</td><td><code>/stocktake</code> · <code>/{id}/confirm</code> · <code>/{id}/cancel</code></td><td>盘点单建单 / 调平 / 作废</td></tr><tr><td>GET</td><td><code>/report/io</code> · <code>/report/aging</code> · <code>/report/stale</code></td><td>收发存 / 库龄四档 / 呆滞</td></tr><tr><td>GET</td><td><code>/pda/resolve?code=</code></td><td>扫码解析：码 → 单据/物料/库位，PDA 端统一入口（收货、上架、拣货、盘点复用上面这些接口）</td></tr></tbody></table><p>完整请求体、响应体、错误码与幂等约定见工程 <code>docs/04-接口设计.md</code>。</p><p>状态机不写在 if-else 里：统一走 <code>StatusMachine</code> + <code>ILLEGAL_TRANSITION</code>，非法流转返回 409。与 <a href="./mes.html#状态机">MES 状态机</a> 同一套做法。</p><h2 id="技术栈与架构" tabindex="-1">技术栈与架构 <a class="header-anchor" href="#技术栈与架构" aria-label="Permalink to “技术栈与架构”">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>技术</th><th>职责</th></tr></thead><tbody><tr><td>后端</td><td>Java 21 · Spring Boot 3.5 · MyBatis</td><td>REST、事务、库存扣减（正确性靠 DB 行锁 + 条件更新，不靠分布式锁）</td></tr><tr><td>前端</td><td>Vue 3 · TypeScript · Element Plus</td><td>管理端 13 条业务路由（10 个列表页 + 3 个详情页）</td></tr><tr><td>终端</td><td>浏览器 + PDA 壳</td><td><code>/pda</code> 扫枪键盘楔；无独立 App</td></tr><tr><td>存储</td><td>MySQL 8（<code>openbiz_wms</code>）</td><td>17 张业务表 + 2 个对账视图 + 2 个流水触发器</td></tr><tr><td>缓存</td><td>Redis</td><td>只给底座用（token / 会话），<strong>不参与库存扣减</strong></td></tr><tr><td>消息</td><td>未接 MQ</td><td>与 MES / ERP 的联动只有设计稿，无生产者也无消费者</td></tr><tr><td>底座</td><td>OpenBiz saas-core + RuoYi 登录外壳</td><td>多租户 / 权限 / 审计 / 备份</td></tr></tbody></table>`,28)),(e(),o("svg",s,[...t[1]||(t[1]=[d('<rect x="0" y="0" width="880" height="292" rx="14" fill="var(--vp-c-bg-soft)"></rect><text x="124" y="38" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">接口</text><rect x="140" y="16" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="158" y="38" font-size="13" fill="var(--vp-c-text-1)">web/ · 11 个 Controller · 68 个方法级端点</text><text x="844" y="38" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">校验 · 租户 · 幂等</text><text x="124" y="84" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">应用</text><rect x="140" y="62" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="158" y="84" font-size="13" fill="var(--vp-c-text-1)">application/ · 用例编排</text><text x="844" y="84" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">入 / 出 / 移库 / 盘点事务边界</text><text x="124" y="130" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">领域</text><rect x="140" y="108" width="720" height="34" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="158" y="130" font-size="13" fill="var(--vp-c-text-1)">domain/ · 库存 · 库位 · 批次 · 策略 · 状态机</text><text x="844" y="130" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">扣减与预占只在这里发生</text><text x="124" y="176" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">持久</text><rect x="140" y="154" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="158" y="176" font-size="13" fill="var(--vp-c-text-1)">mapper/ · MyBatis</text><text x="844" y="176" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">CAS 更新、流水只 INSERT</text><text x="124" y="222" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">设施</text><rect x="140" y="200" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="158" y="222" font-size="13" fill="var(--vp-c-text-1)">infrastructure/ · 打印 · Excel · 备份</text><text x="844" y="222" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">标签模板、导入导出、mysqldump</text><text x="124" y="268" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">底座</text><rect x="140" y="246" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)" stroke-dasharray="5 4"></rect><text x="158" y="268" font-size="13" fill="var(--vp-c-text-1)">openbiz-saas-core · 多租户 / 权限 / 状态机</text><text x="844" y="268" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">MySQL openbiz_wms</text>',25)])])),t[4]||(t[4]=d(`<p>工程目录：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openbiz-wms-app/</span></span>
<span class="line"><span>├── backend/     # Spring Boot · 端口 18086</span></span>
<span class="line"><span>├── frontend/    # Vue3/TS</span></span>
<span class="line"><span>├── sql/         # 业务表</span></span>
<span class="line"><span>├── scripts/     # E2E 验收脚本</span></span>
<span class="line"><span>└── README.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="库存模型" tabindex="-1">库存模型 <a class="header-anchor" href="#库存模型" aria-label="Permalink to “库存模型”">​</a></h2><p>余额拆三态。单字段 <code>qty</code> 一定会在「已分配未发货」时出错：账面有货，实际发不出。</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>谁改</th></tr></thead><tbody><tr><td><code>on_hand</code></td><td>账面实存，货在仓库里就算</td><td>收货 <code>+</code> / 上架 <code>-</code>(出待检位) <code>+</code>(入存储位) / 发货 <code>-</code> / 盘盈亏 <code>±</code></td></tr><tr><td><code>reserved</code></td><td>已被出库单占用，货还在架上</td><td>分配 <code>+</code> / 发货 <code>-</code> / 取消 <code>-</code></td></tr><tr><td><code>locked</code></td><td>质检待判、盘点锁定、异常冻结</td><td>收货入待检 <code>+</code> / 上架出待检 <code>-</code> / 冻结 <code>+</code> / 解冻 <code>-</code></td></tr><tr><td><code>available</code></td><td>可用，能被新单据分配</td><td><strong>生成列，没人直接写</strong>：<code>on_hand - reserved - locked</code></td></tr></tbody></table><p>两条约束：三态均不得为负（<code>CHECK</code>）；任意时刻 <code>SUM(flow.qty_change) = on_hand</code>，且 <code>reserved</code> = 未发货 <code>alloc</code> 合计（两个视图各管一条）。</p><p>扣减分两层，别混着讲：</p><table tabindex="0"><thead><tr><th>层</th><th>目标</th><th>做法</th></tr></thead><tbody><tr><td>正确性 · <strong>P0</strong></td><td>不超卖、余额与流水一致</td><td><code>UPDATE ... WHERE available &gt;= #{n}</code> 单语句 CAS + 同事务写流水；或 <code>reserved</code> 两段式预占</td></tr><tr><td>吞吐 · P2</td><td>万级并发不排队</td><td>库存分桶 / Redis 热点缓存 / 批量合并落库 / 分库</td></tr></tbody></table><p><strong>只有 <code>StockService</code> 能写 <code>wms_stock</code> 与 <code>wms_stock_flow</code></strong>，Controller 与单据 Service 一律不许直接 <code>UPDATE</code>。</p><p>「不可篡改流水」是三条硬约束，不是形容词：</p><ol><li><strong>应用层</strong>：只允许 <code>INSERT</code>，不提供 update / delete 接口，Mapper 不生成对应语句。</li><li><strong>数据库层</strong>：<code>REVOKE UPDATE, DELETE</code>，或触发器 <code>BEFORE UPDATE / DELETE → SIGNAL SQLSTATE &#39;45000&#39;</code>，绕过应用层的写也失败。</li><li><strong>字段一次写全</strong>：<code>doc_no</code> · <code>biz_type</code> · <code>sku_id</code> · <code>batch_id</code> · <code>location_id</code> · <code>qty_change</code> · <code>qty_before</code> · <code>qty_after</code> · <code>operator</code> · <code>occurred_at</code>。</li></ol><p>冲红也走 INSERT（反向 <code>qty_change</code>），不改历史行 —— 按时间轴累加即可复现任意时点库存。细节见 <a href="/my-vitepress-site/scenarios/inventory-deduction.html">库存并发扣减与防超卖</a>。</p><h2 id="系统边界" tabindex="-1">系统边界 <a class="header-anchor" href="#系统边界" aria-label="Permalink to “系统边界”">​</a></h2><table tabindex="0"><thead><tr><th>协同</th><th>链路</th><th>方向</th><th>现状</th></tr></thead><tbody><tr><td>MES</td><td>开工领料 → WMS 出库 → 回写</td><td>MES ↔ WMS</td><td>📋 设计稿有 <code>POST /open/v1/picking-request</code>，代码未实装</td></tr><tr><td>MES</td><td>完工 → WMS 生产入库上架</td><td>MES ↔ WMS</td><td>📋 设计稿有 <code>POST /open/v1/production-inbound</code>，代码未实装</td></tr><tr><td>IIoT</td><td>AGV / 立库状态 → 调度</td><td>IIoT → WMS</td><td>📋 P2</td></tr><tr><td>ERP</td><td>采购 / 销售订单 → 入出库单</td><td>ERP ↔ WMS</td><td>📋 P1；<code>source_doc_no</code> 幂等字段已留，但无调用方</td></tr></tbody></table><p>原则：各系统独立库、不共享表；将来同步走 OpenAPI、异步走 MQ；<code>tenantId</code> 全程透传。</p><p>但要讲清楚现状：<strong>当前 WMS 没有任何跨系统调用</strong>——全库 grep 不到 HTTP client，也没有 MQ 生产者 / 消费者，<code>/open/v1/**</code> 只存在于 <code>docs/04-接口设计.md</code>。能做的是「别的系统按 WMS 的入出库接口来建单」，反过来 WMS 不主动推事件。这一层属于真正落地时补的第一块，不是已经具备的能力。</p><h2 id="路线与验收" tabindex="-1">路线与验收 <a class="header-anchor" href="#路线与验收" aria-label="Permalink to “路线与验收”">​</a></h2><ol><li><strong>阶段一（最小闭环）</strong>：建 <code>openbiz-wms-app</code>，核心表 + 「收货 → 上架 → 流水 → 拣货 → 发货」单链 E2E —— <strong>已达成</strong></li><li><strong>阶段二（Sprint 1 / Sprint 2 已完成）</strong>：Excel / 打印 / 退货 / 多租户 / 盘点 / 报表 / 移库调拨 / PDA 扫码 —— <strong>已达成</strong>（<code>verify_all</code> 13 套 297 项）</li><li><strong>阶段三（未开始）</strong>：批次正反向追溯、预警、与 MES / ERP 开放接口；TMS / IIoT / 性能与行业模板靠后</li></ol><p>阶段一做到下面 7 条才算跑通：</p><table tabindex="0"><thead><tr><th>#</th><th>验收项</th><th>通过标准</th><th>实测</th></tr></thead><tbody><tr><td>1</td><td>链路</td><td>建入库单 → 收货 → 质检 → 上架 → 建出库单 → 分配 → 拣货 → 发货，全程无手工改库</td><td>✅ <code>e2e_wms.py</code> 42 项</td></tr><tr><td>2</td><td>建表</td><td>17 张表（主数据 5 / 单据 4 / 库存 3 / 单号序列 1 / 盘点 2 / 移库 2）+ 2 个对账视图 + 2 个流水触发器，种子数据含 WH01 / 待检位 / SKU</td><td>✅ 见 <code>sql/</code> 11 个脚本</td></tr><tr><td>3</td><td>接口</td><td>上表关键接口可用（全量 68 个方法级端点，11 个 Controller），非法状态流转返回 409</td><td>✅</td></tr><tr><td>4</td><td>库存</td><td>上架后 <code>on_hand</code> 增、发货后 <code>on_hand</code> 与 <code>reserved</code> 同减；两条对账视图 <code>diff</code> 恒为 0</td><td>✅ <code>stockDiff=0</code> / <code>reserveDiff=0</code></td></tr><tr><td>5</td><td>并发</td><td>同一 SKU 并发 100 次发货，成功数 = 实际库存数，<code>available</code> 从不为负</td><td>✅ 恰好 10 成功，7 项断言</td></tr><tr><td>6</td><td>流水</td><td>无任何 update / delete 入口；直接 <code>UPDATE wms_stock_flow</code> 被数据库拒绝</td><td>✅ 触发器 <code>trg_wms_flow_no_update</code> / <code>no_delete</code></td></tr><tr><td>7</td><td>E2E</td><td>一条可重复执行的脚本跑完整条链并断言库存，落在 <code>scripts/</code></td><td>✅ <code>run_wms_e2e.sh</code>，连跑两次 exit 0</td></tr></tbody></table><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li>模块总览：<a href="/my-vitepress-site/instances/industrial/">02 工业数字化应用</a></li><li>同套件：<a href="./mes.html">MES</a> · <a href="./iiot.html">IIoT</a></li><li>关联方案：<a href="/my-vitepress-site/scenarios/inventory-deduction.html">库存并发扣减</a> · <a href="/my-vitepress-site/scenarios/batch-fefo.html">批次 FEFO</a> · <a href="/my-vitepress-site/scenarios/location-allocation.html">库位分配</a></li><li>设计文档：<code>E:/8.cangku/for-job/openbiz-wms-app/docs/</code>（<strong>22 篇</strong>，00 开源参考 → 04 接口设计 → 06 验收清单 → 16 报表 / 17 移库 / 18 PDA → 20 操作日志 / 21 CI·Docker / 22 Swagger）</li><li>实证（2026-11-02 更新）： <ul><li><strong>一键验收</strong> <code>bash scripts/verify_all.sh</code> → 13 个套件 <strong>297 项断言</strong>（单测 34 + 交付 27 + 权限 46 + 审计 15 + 盘点 35 + 备份 16 + Excel 18 + 打印 16 + 退货 17 + 多租户 18 + 报表 22 + 移库 22 + PDA 11）</li><li><strong>主链路 E2E</strong> <code>bash scripts/run_wms_e2e.sh</code> → <code>e2e_wms.py</code> <strong>42 项</strong> + <code>concurrency_check.py</code> <strong>7 项</strong>（100 并发恰好 10 成功、零超卖）</li><li><strong>前端 UI 冒烟</strong> <code>ui_smoke.py</code> → <strong>38 项</strong>（8 个管理端页面：SKU / 库位 / 批次 / 入库 / 出库 / 库存 / 流水 / 主数据，真实点击增删改、列表→详情、零 console error）；移库 / 报表 / 盘点 / PDA 页面尚未纳入 UI 冒烟</li><li>证据文件：工程根目录 <code>E2E-RESULT.txt</code> · <code>UI-SMOKE-RESULT.txt</code> · <code>screenshots/</code></li></ul></li></ul><blockquote><p>已知未覆盖：<code>PRODUCTION</code> / <code>PICKING</code> 只有类型值没有专属分支；移库只有 HTTP 验收、没有单元测试；无开放接口、无 MQ；PDA 是浏览器壳（键盘楔）非原生 App；并发只验了 100 这一档。</p></blockquote><hr><p>上一级：<a href="/my-vitepress-site/instances/industrial/">02 工业数字化应用</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>`,25))])}const f=r(c,[["render",i]]);export{b as __pageData,f as default};
